/// <summary>
/// Item status helper class
/// </summary>
class METChangeItemStatusHelper
{
}

Method.Source:
/// <summary>
/// Update all transfer sites
/// </summary>
/// <param name = "_itemId">ItemId</param>
/// <param name = "_inventSiteId">InventSiteId</param>
/// <param name = "_status">METItemStatus</param>
public void updateItemStatusOfTransferSite(ItemId _itemId, InventSiteId _inventSiteId, METItemStatus _status)
{       
    if (!_itemId || !_inventSiteId)
    {
        return;
    }
    Set transferredSites = new Set(Types::String);
    Set visitedSites = new Set(Types::String);
    container toVisit;

    InventParameters inventParameters = InventParameters::find();

    toVisit = [_inventSiteId];

    for (int i = 1; i<= conLen(toVisit); i++)
    {
        str currentSite = conPeek(toVisit, i);

        // Skip if already visited
        if (visitedSites.in(currentSite))
        {
            continue;
        }
        if (currentSite)
        {
            METReqItemTableInventDimView metReqItemTableInventDimViewLocal;
            METItemStatusWarehouses metItemStatusWarehousesLocal;

            select metReqItemTableInventDimViewLocal
                where metReqItemTableInventDimViewLocal.ItemId == _itemId
                && metReqItemTableInventDimViewLocal.InventSiteId != currentSite
                && metReqItemTableInventDimViewLocal.ReqPOType == ReqPOType::Transfer
                && metReqItemTableInventDimViewLocal.MainWarehouseInventSiteId == currentSite
                notexists join metItemStatusWarehousesLocal
                where metItemStatusWarehousesLocal.InventLocationId == metReqItemTableInventDimViewLocal.InventLocationId;

            if (metReqItemTableInventDimViewLocal && !this.changeStatusToDeleted_Validate(metReqItemTableInventDimViewLocal, metReqItemTableInventDimViewLocal.ItemId))
            {
                continue; //If validation fails, skip processing this site
            }
        }


        visitedSites.add(currentSite);

        METReqItemTableInventDimView metReqItemTableInventDimView;
        METItemStatusWarehouses metItemStatusWarehouses;

        while select metReqItemTableInventDimView
        where metReqItemTableInventDimView.ItemId == _itemId
        && metReqItemTableInventDimView.InventSiteId != currentSite
        && metReqItemTableInventDimView.ReqPOType == ReqPOType::Transfer
        && metReqItemTableInventDimView.MainWarehouseInventSiteId == currentSite
        notexists join metItemStatusWarehouses
        where metItemStatusWarehouses.InventLocationId == metReqItemTableInventDimView.InventLocationId
        {
            if (!transferredSites.in(metReqItemTableInventDimView.InventSiteId))
            {
                transferredSites.add( metReqItemTableInventDimView.InventSiteId);
                toVisit += metReqItemTableInventDimView.InventSiteId; // Enqueue next site

                if (metReqItemTableInventDimView) // Activate Item Status
                {
                    if (_status == METConstants::Active)
                    {
                        this.updateInsertStatusToActive(metReqItemTableInventDimView);
                    }
                    else if (_status == METConstants::NewStr)
                    {
                        this.updateInsertStatusToNew(metReqItemTableInventDimView);
                    }
                    else if (_status == METConstants::Deleted && this.changeStatusToDeleted_Validate(metReqItemTableInventDimView, metReqItemTableInventDimView.itemid))
                    {
                        METInventItemOrderSetup metInventItemOrderSetupForDelete = METInventItemOrderSetup::findByItemAndSite(metReqItemTableInventDimView.ItemId, metReqItemTableInventDimView.InventSiteId);

                        this.updateStatusToDeleted(metInventItemOrderSetupForDelete,metInventItemOrderSetupForDelete.InventDimId);
                    }
                }                                        
            }
        }
    }
}

private boolean changeStatusToDeleted_Validate(metReqItemTableInventDimView _metReqItemTableInventDimView, ItemId _itemId)
{
    boolean ret = true;

    InventWarehouseOnHandIncludingCWItemAggregatedView  inventOnHandView;
    InventWarehouseOnHandIncludingCatchWeightItemEntity inventOnHandEntity;
    METReqItemTable metReqItemTable = METReqItemTable::find(_metReqItemTableInventDimView.ReqItemTableRecId);

    select firstonly inventOnHandView
            where inventOnHandView.ItemNumber == _itemId
                && inventOnHandView.InventorySiteId == _metReqItemTableInventDimView.InventSiteId
                && inventOnHandView.InventoryWarehouseId == _metReqItemTableInventDimView.InventLocationId;

    if (inventOnHandView.AvailableOnHandQuantityMapped || inventOnHandView.PdsCWAvailOnHandQuantityMapped)
    {
        ret = checkFailed(strfmt("@MET:OnHandValidation", _itemId,_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId));
    }
    if (inventOnHandView.OrderedQuantityMapped || inventOnHandView.PdsCWOrderedQuantityMapped || inventOnHandView.ReservedOnHandQuantityMapped ||
            inventOnHandView.PdsCWReservOnHandQuantityMapped || inventOnHandView.ReservedOrderedQuantityMapped)
    {
        ret = checkFailed(strfmt("@MET:OpenPOTOValidation", _itemId,_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
    }
    if (metReqItemTable.SlotLoc1Area)
    {
        ret = checkFailed(strfmt("@MET:SlotLocation1Validation", _itemId,_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
    }
    if (metReqItemTable.SlotLoc2Area)
    {
        ret = checkFailed(strfmt("@MET:SlotLocation2Validation",_itemId,_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId))&& ret;
    }
    if (inventOnHandView.AvailableOnHandQuantity || inventOnHandView.AvailableOrderedQuantity || inventOnHandView.AvailableOrderedQuantityMapped || inventOnHandView.OnOrderQuantity || inventOnHandView.ReservedOnHandQuantity || inventOnHandView.ReservedOrderedQuantityMapped || inventOnHandView.TotalAvailableQuantity)
    {
        ret = checkFailed(strfmt("@MET:OpenSOITValidation", _itemId,_metReqItemTableInventDimView.InventSiteId, _metReqItemTableInventDimView.InventLocationId)) && ret;
    }

    return ret;
}

/// <summary>
/// Update status to Active
/// </summary>
/// <param name = "_metReqItemTableInventDimView">METReqItemTableInventDimView</param>
public void updateInsertStatusToActive(METReqItemTableInventDimView _metReqItemTableInventDimView)
{
    METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metReqItemTableInventDimView.ItemId, _metReqItemTableInventDimView.InventSiteId, true);

    if (!metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventDim inventDimLocal;

        select firstonly InventDimId from inventItemPurchSetupLocal
            exists join inventDimLocal
            where inventDimLocal.InventSiteId == _metReqItemTableInventDimView.InventSiteId
            && inventItemPurchSetupLocal.ItemId ==  metInventItemOrderSetup.ItemId
            && inventDimLocal.inventDimId == inventItemPurchSetupLocal.InventDimId;

        metInventItemOrderSetupLocal.ItemId = metInventItemOrderSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetupLocal.InventDimId;
        metInventItemOrderSetupLocal.SiteId = _metReqItemTableInventDimView.InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        metInventItemOrderSetupLocal.PublishPriceBook  = true;
        metInventItemOrderSetupLocal.PublishPortal = true;
        metInventItemOrderSetupLocal.PublishHost = true;
        metInventItemOrderSetupLocal.insert();
    }
    else
    {
        metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::Active).ItemStatus;
        metInventItemOrderSetup.PublishPriceBook    = true;
        metInventItemOrderSetup.PublishPortal       = true;
        metInventItemOrderSetup.PublishHost         = true;
        metInventItemOrderSetup.update();
    }
}

/// <summary>
/// Update status to NEW
/// </summary>
/// <param name = "_metReqItemTableInventDimView">METReqItemTableInventDimView</param>
public void updateInsertStatusToNew(METReqItemTableInventDimView _metReqItemTableInventDimView)
{
    METInventItemOrderSetup metInventItemOrderSetup = METInventItemOrderSetup::findByItemAndSite(_metReqItemTableInventDimView.ItemId, _metReqItemTableInventDimView.InventSiteId, true);

    if (!metInventItemOrderSetup)
    {
        METInventItemOrderSetup metInventItemOrderSetupLocal;
        InventItemPurchSetup inventItemPurchSetupLocal;
        InventDim inventDimLocal;

        select firstonly InventDimId from inventItemPurchSetupLocal
            exists join inventDimLocal
            where inventDimLocal.InventSiteId == _metReqItemTableInventDimView.InventSiteId
            && inventItemPurchSetupLocal.ItemId ==  metInventItemOrderSetup.ItemId
            && inventDimLocal.inventDimId == inventItemPurchSetupLocal.InventDimId;

        metInventItemOrderSetupLocal.ItemId = metInventItemOrderSetup.ItemId;
        metInventItemOrderSetupLocal.InventDimId = inventItemPurchSetupLocal.InventDimId;
        metInventItemOrderSetupLocal.SiteId = _metReqItemTableInventDimView.InventSiteId;
        metInventItemOrderSetupLocal.ItemStatus = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetupLocal.insert();
    }
    else
    {
        metInventItemOrderSetup.ItemStatus          = METItemStatusTable::findByStatus(METItemsStatus::New).ItemStatus;
        metInventItemOrderSetup.PublishPriceBook    = false;
        metInventItemOrderSetup.PublishPortal       = false;
        metInventItemOrderSetup.PublishHost         = false;
        metInventItemOrderSetup.update();
    }
}

/// <summary>
/// Update status to Delete
/// </summary>
/// <param name = "_metInventItemOrderSetup">METInventItemOrderSetup</param>
/// <param name = "_inventDimId">InventDimId</param>
private void updateStatusToDeleted( METInventItemOrderSetup     _metInventItemOrderSetup,
                                    InventDimId                 _inventDimId)
{
    if (_metInventItemOrderSetup)
    {
        ttsbegin;
        _metInventItemOrderSetup.selectForUpdate(true);
        _metInventItemOrderSetup.ItemStatus         = METConstants::Deleted;
        _metInventItemOrderSetup.DeleteStatusDate   = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
        _metInventItemOrderSetup.SubrangeId         = '';
        _metInventItemOrderSetup.SubrangeDesc       = '';
        _metInventItemOrderSetup.update();
        ttscommit;

        InventItemInventSetup inventItemInventSetup     = InventItemInventSetup::find(_metInventItemOrderSetup.ItemId, _inventDimId,true);
        InventItemPurchSetup inventItemPurchSetup       = InventItemPurchSetup::find(_metInventItemOrderSetup.ItemId, _inventDimId, true);

        if (inventItemInventSetup)
        {
            ttsbegin;
            inventItemInventSetup.Override = true;
            inventItemInventSetup.Stopped = true;
            inventItemInventSetup.update();
            ttscommit;
        }
        if (inventItemPurchSetup)
        {
            ttsbegin;
            inventItemPurchSetup.Override = true;
            inventItemPurchSetup.Stopped = true;
            inventItemPurchSetup.update();
            ttscommit;
        }

    }
}
